mapper.select:
SELECT mn.*, con.Con_Name as conName, pp.P_Name as pName, (SELECT GROUP_CONCAT(sc.C_name) FROM punishes_conpartb b JOIN sys_Company sc ON b.C_Id = sc.C_Id WHERE b.Pun_Id = mn.id) AS cName FROM Punishes mn LEFT JOIN Con_Contract con ON con.Con_Id = mn.Con_Id LEFT JOIN Pre_Project pp ON pp.P_Id = mn.P_ID ${params.authSql}
AND likePname(#{params.pName},pp.P_Id)=true
AND pp.P_Name LIKE CONCAT('%',#{params.pName},'%')
AND con.Con_Name LIKE CONCAT('%',#{params.conName},'%')
AND mn.Punish_Type = #{params.punishType}
AND EXISTS ( SELECT 1 FROM punishes_conpartb b JOIN sys_Company sc ON b.C_Id = sc.C_Id WHERE b.Pun_Id = mn.id AND sc.C_name LIKE CONCAT('%', #{params.cName}, '%') )
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time desc

SELECT mn.*, con.Con_Name as conName, pp.P_Name as pName, (SELECT LISTAGG(sc.C_name, ',') WITHIN GROUP (ORDER BY sc.C_name) FROM punishes_conpartb b JOIN sys_Company sc ON b.C_Id = sc.C_Id WHERE b.Pun_Id = mn.id) AS cName FROM Punishes mn LEFT JOIN Con_Contract con ON con.Con_Id = mn.Con_Id LEFT JOIN Pre_Project pp ON pp.P_Id = mn.P_ID ${params.authSql}
AND likePname(#{params.pName},pp.P_Id)=true
AND pp.P_Name LIKE CONCAT('%',#{params.pName},'%')
AND con.Con_Name LIKE CONCAT('%',#{params.conName},'%')
AND mn.Punish_Type LIKE CONCAT('%',#{params.punishType},'%')
AND EXISTS ( SELECT 1 FROM punishes_conpartb b JOIN sys_Company sc ON b.C_Id = sc.C_Id WHERE b.Pun_Id = mn.id AND sc.C_name LIKE CONCAT('%', #{params.cName}, '%') )
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time desc
